using Microsoft.EntityFrameworkCore;using ZMAllied.Application.Common;using ZMAllied.Application.Interfaces;using ZMAllied.Domain.Entities.Organization;using ZMAllied.Infrastructure.Persistence;namespace ZMAllied.Infrastructure.Repositories{public class CompanyRateRepository(ZMAlliedDbContext c):ICompanyRateRepository{public Task<CompanyRate?>GetByIdAsync(int id)=>c.CompanyRates.FindAsync(id).AsTask();public Task<CompanyRate?>GetByCompanyIdAsync(int id)=>c.CompanyRates.FirstOrDefaultAsync(x=>x.CompanyId==id&&!x.IsDeleted);public async Task<PagedResult<CompanyRate>>GetPagedAsync(int p,int s,int?companyId){var x=c.CompanyRates.Where(e=>!e.IsDeleted);if(companyId.HasValue)x=x.Where(e=>e.CompanyId==companyId.Value);return new(){Items=await x.OrderByDescending(e=>e.EffectiveFrom).Skip((p-1)*s).Take(s).ToListAsync(),PageNumber=p,PageSize=s,TotalCount=await x.CountAsync()};}public async Task<CompanyRate>AddAsync(CompanyRate x){c.CompanyRates.Add(x);await c.SaveChangesAsync();return x;}public async Task UpdateAsync(CompanyRate x){c.CompanyRates.Update(x);await c.SaveChangesAsync();}public Task<bool>CompanyExistsAsync(int id)=>c.Companies.AnyAsync(x=>x.Id==id&&!x.IsDeleted);}}
